import csv
import io
import re
from typing import List, Dict, Any


def parse_csv(raw_csv: str) -> Dict[str, Any]:
    expected_width = 14
    try:
        records = list(csv.reader(io.StringIO(raw_csv, newline=""), delimiter=",", quotechar='"', strict=False))
    except csv.Error:
        records = []

    records = [row for row in records if row and any(value.strip() for value in row)]
    if not records:
        return {"columns": [], "rows": []}

    def looks_like_header(row: List[str]) -> bool:
        if len(row) != expected_width:
            return False
        identifier_count = sum(
            bool(re.fullmatch(r"[A-Za-z_][A-Za-z0-9_ ]*", value.strip()))
            for value in row
        )
        return identifier_count >= max(3, int(expected_width * 0.65))

    header_index = next(
        (index for index, row in enumerate(records) if looks_like_header(row)),
        0,
    )
    columns = [value.strip() for value in records[header_index]]
    data = records[header_index + 1:]

    width = max([len(columns)] + [len(row) for row in data])
    original_width = len(columns)
    for index in range(original_width, width):
        columns.append("extra_" + str(index - original_width + 1))

    rows = []
    for row in data:
        normalized = list(row[:width])
        normalized.extend([""] * (width - len(normalized)))
        rows.append(normalized)

    return {"columns": columns, "rows": rows}
